Definition INVC (X : extras) (st : mstate) (L : mled) (BL : list blk) (LS : lhead -> list aptr) : Prop :=
  inv_R X st L /\ inv_A st /\ inv_M X st LS /\ inv_L st LS /\ inv_G X st LS /\ inv_S X st BL.

